def dependents(graph: dict[str, Any], order: list[str], start: str) -> list[str]:
    """`start` plus every later node that (transitively) consumes a token it produces."""
    if start not in order:
        raise HarnessError(f"{start} is not in this ticket's trace")
    stale = [start]
    tokens = set(graph["nodes"][start].get("produces", []))
    for node_id in order[order.index(start) + 1:]:
        spec = graph["nodes"][node_id]
        if tokens & set(spec.get("requires", [])):
            stale.append(node_id)
            tokens |= set(spec.get("produces", []))
    return stale

# `feeds`: an extension node hands its tokens to named core nodes, so they wait for it (inert when the
# family is off, because no node in the trace produces the token).
for node_id, spec in list(nodes.items()):
    for target in spec.get("feeds", []):
        if target not in nodes:
            raise HarnessError(f"{node_id} feeds unknown node {target}")
        nodes[target] = {**nodes[target], "requires": list(dict.fromkeys(nodes[target].get("requires", []) + spec["produces"]))}

def missing_prerequisites(graph: dict[str, Any], order: list[str], state: dict[str, Any], node: str) -> list[str]:
    """Readiness = every token the node requires is produced by a settled node of the trace.
    A token no node in the trace produces is inert (e.g. a family-only token)."""
    producers: dict[str, list[str]] = {}
    for n in order:
        for tok in graph["nodes"][n].get("produces", []):
            producers.setdefault(tok, []).append(n)
    missing = []
    for tok in graph["nodes"][node].get("requires", []):
        owners = [n for n in producers.get(tok, []) if n != node]
        if owners and not any(settled(state, n) for n in owners):
            missing.append(f"{tok} (from {', '.join(owners)})")
    return missing

def save(self, state: dict[str, Any]) -> None:
    self.dir.mkdir(parents=True, exist_ok=True)
    tmp = self.state_path.with_suffix(".tmp")
    tmp.write_text(json.dumps(state, indent=2, ensure_ascii=False), encoding="utf-8")
    for attempt in range(20):  # Windows: AV/indexer can hold the target for a moment
        try:
            tmp.replace(self.state_path)
            return
        except PermissionError:
            if attempt == 19:
                raise HarnessError(f"G7: cannot replace {self.state_path} (file locked)")
            time.sleep(0.05 * (attempt + 1))

def log(self, event: dict[str, Any]) -> dict[str, Any]:
    self.dir.mkdir(parents=True, exist_ok=True)
    event = {"at": now(), **event}
    with self.log_path.open("a", encoding="utf-8") as fh:
        fh.write(json.dumps(event, ensure_ascii=False) + "\n")
    return event

def repo_subject(path: str) -> dict[str, str]:
    """Digest of what would be shipped: HEAD + uncommitted diff + untracked file list."""
    head = _git(path, "rev-parse", "HEAD").strip()
    diff = _git(path, "diff", "HEAD", "--binary")
    untracked = _git(path, "ls-files", "--others", "--exclude-standard")
    return {"head": head, "subject": sha256_text(head + "\n" + diff + "\n" + untracked)}

def check_receipts(state: dict[str, Any], min_hours_left: int) -> list[str]:
    problems = []
    receipts = state.get("receipts") or {}
    limit = datetime.now(timezone.utc) + timedelta(hours=min_hours_left)
    for repo in state["context"]["repositories"]:
        rec = receipts.get(repo["id"])
        if not rec:
            problems.append(f"{repo['id']}: no receipt (rerun final-review)")
            continue
        if datetime.fromisoformat(rec["expiresAt"]) < limit:
            problems.append(f"{repo['id']}: receipt expires {rec['expiresAt']} (< {min_hours_left}h left) - re-issue from final-review, do not invalidate")
            continue
        current = repo_subject(repo.get("worktree") or repo["path"])["subject"]
        if current != rec["subject"]:
            problems.append(f"{repo['id']}: checkout changed since the receipt - invalidate the node that owns the change")
    return problems

def ticket_root(profile: dict[str, Any], pdir: Path) -> Path:
    root = Path(profile["paths"]["ticketRoot"])
